// The contract checks between src/ipc.rs (exported by ts-rs into
// ./generated by `cargo test`, see ipc::tests) and one renderer's
// ipc/types.ts, generic over that renderer (`Own`) and the other one
// (`Other`). tests/ipc_contract_poe{1,2}.ts instantiate them; each fails to
// compile naming the offending event(s). Run `cargo test rust_ipc_types` to
// regenerate and re-check.
import type { ClientEvent } from './generated/ClientEvent'
import type { MainEvent } from './generated/MainEvent'

type Event = { name: string }
type PayloadOf<E> = E extends { payload: infer P } ? P : undefined
type Named<U, N> = Extract<U, { name: N }>
type Incoming<E extends Event> = Extract<E['name'], `CLIENT->MAIN::${string}` | `OVERLAY->MAIN::${string}`>

export type Verdict<Bad> = [Bad] extends [never] ? 'ok' : Bad

// ClientEvent parses both renderers' events, so the name checks run over
// both: every event either renderer can send is one ClientEvent parses (or
// knows to ignore)...
export type Unhandled<Own extends Event, Other extends Event> =
  Exclude<Incoming<Own> | Incoming<Other>, ClientEvent['name']>
// ...and ClientEvent names no event neither renderer sends.
export type UnknownIncoming<Own extends Event, Other extends Event> =
  Exclude<ClientEvent['name'], Incoming<Own> | Incoming<Other>>
// Whatever this renderer sends fits our struct: our fields exist with our
// types. (Events it doesn't send have payload `never`, which fits.)
export type BadIncoming<Own extends Event> = {
  [N in ClientEvent['name']]: [PayloadOf<Named<Own, N>>] extends [PayloadOf<Named<ClientEvent, N>>] ? never : N
}[ClientEvent['name']]

// Everything we send exists in this renderer...
export type UnknownOutgoing<Own extends Event> = Exclude<MainEvent['name'], Own['name']>
// ...and has every field it expects, with its type.
export type BadOutgoing<Own extends Event> = {
  [N in MainEvent['name']]: [PayloadOf<Named<MainEvent, N>>] extends [PayloadOf<Named<Own, N>>] ? never : N
}[MainEvent['name']]
